// Next Greater Element using Monotonic Stack
var stack = AnimatedStack<Int>()
let nums = [4, 5, 2, 25]

func nextGreaterElement(_ nums: [Int], s: inout AnimatedStack<Int>) -> [Int] {
    var result = [Int](repeating: -1, count: nums.count)
    for i in 0..<nums.count {
        while !s.isEmpty {
            if let topIdx = s.peek(), nums[i] > nums[topIdx] {
                result[topIdx] = nums[i]
                s.pop()
            } else {
                break
            }
        }
        s.push(i)
    }
    return result
}

let result = nextGreaterElement(nums, s: &stack)
